package com.wizzadrds.theworldremembers.voice; import java.io.*; import java.nio.file.*; public final class LocalProcessSttAdapter implements SttAdapter{private final java.util.List<String> command;public LocalProcessSttAdapter(java.util.List<String> command){if(command.isEmpty())throw new IllegalArgumentException();this.command=java.util.List.copyOf(command);}public String transcribe(byte[] pcm) throws IOException,InterruptedException{Path f=Files.createTempFile("twr-stt-",".pcm");try{Files.write(f,pcm);var a=new java.util.ArrayList<>(command);a.add(f.toString());var p=new ProcessBuilder(a).redirectErrorStream(true).start();var out=new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);if(p.waitFor()!=0)throw new IOException("Local STT failed");return out.trim();}finally{Files.deleteIfExists(f);}}}